const amqp = require('amqplib');
const Redis = require('ioredis');
const crypto = require('crypto');

const redis = new Redis(process.env.REDIS_URL || 'redis://localhost:6379');

const RATE_LIMIT_WINDOW = 60;
const RATE_LIMIT_MAX = 100;
const MAX_RETRIES = 3;
const RETRY_DELAY_MS = 1000;

class TransactionProcessor {
  constructor() {
    this.pendingSettlements = new Map();
  }

  async processTransfer(msg) {
    const { from, to, amount, requestId } = msg;

    if (typeof amount !== 'number' || amount <= 0 || !Number.isFinite(amount)) {
      return { success: false, error: 'INVALID_AMOUNT' };
    }
    if (!from || !to || from === to) {
      return { success: false, error: 'INVALID_ACCOUNTS' };
    }

    const settlementId = crypto.randomUUID();

    const luaScript = `
      local fromBalance = tonumber(redis.call('get', KEYS[1]) or '0')
      local toBalance = tonumber(redis.call('get', KEYS[2]) or '0')
      local amount = tonumber(ARGV[1])
      if amount <= 0 then
        return 0
      end
      if fromBalance >= amount then
        redis.call('set', KEYS[1], tostring(fromBalance - amount))
        redis.call('set', KEYS[2], tostring(toBalance + amount))
        return 1
      end
      return 0
    `;

    const result = await redis.eval(
      luaScript, 2,
      `balance:${from}`,
      `balance:${to}`,
      amount.toString()
    );

    return { success: result === 1, settlementId };
  }
}

class RateLimiter {
  async checkLimit(clientId) {
    const key = `ratelimit:${clientId}:${Math.floor(Date.now() / 1000 / RATE_LIMIT_WINDOW)}`;
    const current = await redis.incr(key);
    if (current === 1) {
      await redis.expire(key, RATE_LIMIT_WINDOW);
    }
    return current <= RATE_LIMIT_MAX;
  }
}

class MessageQueueConsumer {
  constructor() {
    this.processor = new TransactionProcessor();
    this.rateLimiter = new RateLimiter();
  }

  async connect() {
    this.connection = await amqp.connect(process.env.AMQP_URL || 'amqp://localhost');
    this.channel = await this.connection.createChannel();
    await this.channel.assertQueue('transactions', { durable: true });
    await this.channel.prefetch(10);
  }

  async handleMessage(msg) {
    let content;
    try {
      content = JSON.parse(msg.content.toString());
    } catch (parseErr) {
      // Malformed / poison message: reject without requeue to avoid a crash loop.
      this.channel.nack(msg, false, false);
      return;
    }

    if (!content || typeof content !== 'object') {
      this.channel.nack(msg, false, false);
      return;
    }

    const { clientId, payload, retryCount = 0 } = content;

    if (!clientId || typeof clientId !== 'string' || clientId.length > 128) {
      this.channel.nack(msg, false, false);
      return;
    }

    if (!payload || typeof payload !== 'object') {
      this.channel.nack(msg, false, false);
      return;
    }

    const allowed = await this.rateLimiter.checkLimit(clientId);
    if (!allowed) {
      this.channel.nack(msg, false, false);
      return;
    }

    try {
      const result = await this.processor.processTransfer(payload);

      if (!result.success && result.error === 'INSUFFICIENT_FUNDS' && retryCount < MAX_RETRIES) {
        await this.scheduleRetry(content, retryCount + 1);
        this.channel.ack(msg);
        return;
      }

      await this.publishResult(clientId, payload.requestId, result);
      this.channel.ack(msg);
    } catch (err) {
      if (retryCount < MAX_RETRIES) {
        await this.scheduleRetry(content, retryCount + 1);
        this.channel.ack(msg);
      } else {
        this.channel.nack(msg, false, false);
      }
    }
  }

  async scheduleRetry(content, retryCount) {
    const delay = RETRY_DELAY_MS * Math.pow(2, retryCount - 1);
    setTimeout(async () => {
      const retryMsg = { ...content, retryCount };
      this.channel.sendToQueue('transactions', Buffer.from(JSON.stringify(retryMsg)));
    }, delay);
  }

  async publishResult(clientId, requestId, result) {
    const resultMsg = { clientId, requestId, ...result, timestamp: Date.now() };
    this.channel.sendToQueue('results', Buffer.from(JSON.stringify(resultMsg)));
  }

  async start() {
    await this.connect();
    this.channel.consume('transactions', (msg) => this.handleMessage(msg));
    console.log('Consumer started, waiting for messages...');
  }
}

const consumer = new MessageQueueConsumer();
consumer.start().catch(console.error);

module.exports = { MessageQueueConsumer, TransactionProcessor, RateLimiter };
